$ErrorActionPreference='Stop'
$script=Get-Content(Join-Path $PSScriptRoot 'run-network-delay-scientific.ps1')-Raw
foreach($required in @("RunId = 'ob-netdelay-15u-002'","canonical-utc.ps1","ConvertTo-CanonicalUtcString `$ramp.ramp_end_utc","ConvertTo-CanonicalUtcString `$cleanup.cleanup_utc","[Parameter(Mandatory = `$true)][switch]`$ExecutionApproved","verify-target-pod-stability.ps1","-DurationSeconds','120'","-PollSeconds','5'","AssertLiveProxyContract","--overlay-root","Wait-UntilMinimumUtcDuration -StartUtc `$warmupStart -MinimumSeconds 300","Wait-UntilMinimumUtcDuration -StartUtc `$baselineStart -MinimumSeconds 300","--action ramp","-StartUtc `$rampEnd -MinimumSeconds 300","--action cleanup","-StartUtc `$cooldownStart -MinimumSeconds 300","-TraceQueryChunkSeconds','300'","scientific_validity_gate_failed_evidence_preserved","emergency-cleanup-evidence.json","EmergencyCapture","emergency_archive_telemetry","finalize-run-artifacts.ps1","verify-finalized-run.ps1")){if(-not$script.Contains($required)){throw"runner_contract_missing:$required"}}
if(([regex]::Matches($script,'--action ramp')).Count-ne 1){throw'ramp_call_count_invalid'}
